import awkward as ak
from pocket_coffea.lib.cut_definition import Cut

def dimuon_mask(events, params, **kwargs):
    """
    Mask function for dimuon preselection cut.

    Requires:
    - At least 2 muons with pT above threshold
    - Leading pair with opposite charge
    """
    pt_threshold = params.get("pt_threshold", 15.0)

    # Ensure muons collection exists
    if "Muon" not in events.fields:
        return ak.zeros_like(events.event, dtype=bool)

    muons = events.Muon

    # Count muons above pT threshold
    muons_above_threshold = muons[muons.pt > pt_threshold]
    n_muons = ak.num(muons_above_threshold)

    # Require at least 2 muons above threshold
    has_two_muons = n_muons >= 2

    # Check opposite charge for leading pair
    leading_pair_opposite_charge = ak.fill_none(
        ak.any(
            (muons_above_threshold[:, 0].charge * muons_above_threshold[:, 1].charge) < 0,
            axis=1
        ),
        False
    )

    return has_two_muons & leading_pair_opposite_charge


# Define the cut using PocketCoffea's Cut class
dimuon_cut = Cut(
    name="dimuon",
    function=dimuon_mask,
    params={"pt_threshold": 15.0}
)

